+
+$Title = __('Import Item Notes');
+$ViewTopic = 'SpecialUtilities';
+$BookMark = basename(__FILE__, '.php');
+include('includes/header.php');
+
+echo '<p class="page_title_text"><img alt="" src="' . $RootPath . '/css/' . $Theme .
+		'/images/inventory.png" title="' .
+		__('Import Stock Item Notes from .csv') . '" />' . ' ' .
+		__('Import Stock Item Notes from .csv') . '</p>';
+
+// If this script is called with a file object, then the file contents are imported
+// If this script is called with the gettemplate flag, then a template file is served
+// Otherwise, a file upload form is displayed
+// An item can have any number of notes: one row in the file adds one note to an existing item.
+// Importing the same file twice adds the notes twice.
+
+$FieldHeadings = array(
+	'StockID',	// 0
+	'Note',		// 1
+	'Date'		// 2 optional value, YYYY-MM-DD; today when empty
+);
+
+if (isset($_FILES['userfile']) and $_FILES['userfile']['name']) { //start file processing
+
+	$FieldTarget = count($FieldHeadings);
+	$InputError = 0;
+
+	$FileName = $_FILES['userfile']['name'];
+	$TempName = $_FILES['userfile']['tmp_name'];
+
+	$FileHandle = fopen($TempName, 'r');
+
+	$HeadRow = fgetcsv($FileHandle, 10000, ",", '"');
+	// Remove UTF-8 BOM if present
+	if (substr($HeadRow[0], 0, 3) === "\xef\xbb\xbf") {
+		$HeadRow[0] = substr($HeadRow[0], 3);
+	}
+
+	if (count($HeadRow) != $FieldTarget) {
+		prnMsg(__('File contains') . ' ' . count($HeadRow) . ' ' . __('columns, expected') . ' ' . $FieldTarget . '. ' . __('Try downloading a new template.'), 'error');
+		fclose($FileHandle);
+		include('includes/footer.php');
+		exit();
+	}
+
+	$Head = 0;
+	foreach ($HeadRow as $HeadField) {
+		if (mb_strtoupper(trim($HeadField)) != mb_strtoupper($FieldHeadings[$Head])) {
+			prnMsg(__('File contains incorrect headers') . ' ' . mb_strtoupper($HeadField) . ' != ' . mb_strtoupper($FieldHeadings[$Head]) . '. ' . __('Try downloading a new template.'), 'error');
+			fclose($FileHandle);
+			include('includes/footer.php');
+			exit();
+		}
+		$Head++;
+	}
+
+	DB_Txn_Begin();
+
+	$Row = 1;
+	while (($MyRow = fgetcsv($FileHandle, 10000, ",", '"')) !== false) {
+
+		if ($MyRow === array(null)) { // blank line
+			continue;
+		}
+
+		if (count($MyRow) != $FieldTarget) {
+			prnMsg($FieldTarget . ' ' . __('fields required') . ', ' . count($MyRow) . ' ' . __('fields received'), 'error');
+			DB_Txn_Rollback();
+			fclose($FileHandle);
+			include('includes/footer.php');
+			exit();
+		}
+
+		$StockID = mb_strtoupper(trim($MyRow[0]));
+		$Note = trim($MyRow[1]);
+		$NoteDate = trim($MyRow[2]);
+
+		$Result = DB_query("SELECT COUNT(stockid) FROM stockmaster WHERE stockid='" . DB_escape_string($StockID) . "'");
+		$TestRow = DB_fetch_row($Result);
+		if ($TestRow[0] == 0) {
+			$InputError = 1;
+			prnMsg(__('Stock item') . ' ' . htmlspecialchars($StockID, ENT_QUOTES, 'UTF-8') . ' ' . __('does not exist'), 'error');
+		}
+		if ($Note == '') {
+			$InputError = 1;
+			prnMsg(__('The note may not be empty'), 'error');
+		}
+		if ($NoteDate == '') {
+			$NoteDate = date('Y-m-d');
+		} elseif (!preg_match('/^\d{4}-\d{2}-\d{2}$/', $NoteDate) or !checkdate((int)substr($NoteDate, 5, 2), (int)substr($NoteDate, 8, 2), (int)substr($NoteDate, 0, 4))) {
+			$InputError = 1;
+			prnMsg(__('The date of the note must be a valid date in the format YYYY-MM-DD'), 'error');
+		}
+
+		if ($InputError != 1) {
+			// values from the file are not escaped by the session bootstrap, so do it here, as it does for form input
+			$SQL = "INSERT INTO stockitemnotes (stockid,
+												note,
+												date)
+					VALUES ('" . DB_escape_string($StockID) . "',
+							'" . DB_escape_string(htmlspecialchars($Note, ENT_QUOTES, 'UTF-8')) . "',
+							'" . $NoteDate . "')";
+			$Result = DB_query($SQL, __('The item note could not be added because'));
+		}
+
+		if ($InputError == 1) {
+			break;
+		}
+		$Row++;
+	}
+
+	if ($InputError == 1) {
+		prnMsg(__('Failed on row') . ' ' . $Row . '. ' . __('Batch import has been rolled back.'), 'error');
+		DB_Txn_Rollback();
+	} else {
+		DB_Txn_Commit();
+		prnMsg(__('Batch Import of') . ' ' . htmlspecialchars($FileName, ENT_QUOTES, 'UTF-8') . ' ' . __('has been completed. All transactions committed to the database.'), 'success');
+	}
+
+	fclose($FileHandle);
+
+} elseif (isset($_POST['gettemplate']) or isset($_GET['gettemplate'])) { //download an import template
+
+	echo '<br /><br /><br />"' . implode('","', $FieldHeadings) . '"<br /><br /><br />';
+
+} else { //show file upload form
+
+	echo '<br />
+		<a href="' . $RootPath . '/Z_ImportStockNotes.php?gettemplate=1">' . __('Get Import Template') . '</a>
+		<br />
+		<br />';
+	echo '<form action="' . htmlspecialchars($_SERVER['PHP_SELF'], ENT_QUOTES, 'UTF-8') . '" method="post" enctype="multipart/form-data">';
+	echo '<div class="centre">';
+	echo '<input type="hidden" name="FormID" value="' . $_SESSION['FormID'] . '" />';
+	echo '<input type="hidden" name="MAX_FILE_SIZE" value="1000000" />' .
+			__('Upload file') . ': <input name="userfile" type="file" />
+			<input type="submit" value="' . __('Send File') . '" />
+		</div>
+		</form>';
+}
+
+include('includes/footer.php');
